sql.if:
, WITH RECURSIVE
dt_scope(medata_set_id, depth) AS ( SELECT t1.medata_set_id::text, 0 FROM dtmeta.tb_meta_dataset t1 WHERE t1.medata_set_id = #{digitalTwinId} UNION ALL SELECT t3.medata_val::text, s.depth + 1 FROM dt_scope s JOIN dtmeta.tb_meta_data t3 ON t3.medata_set_id = s.medata_set_id WHERE t3.medata_val IS NOT NULL AND t3.medata_val != '' AND s.depth < 5
AND t3.prpty_id IN #{pid}
)

mapper.select:
WITH RECURSIVE descendants(medata_set_id, depth) AS ( SELECT t1.medata_set_id::text, 0 FROM dtmeta.tb_meta_dataset t1 WHERE t1.medata_set_id = #{id} UNION ALL SELECT t3.medata_val::text, d.depth + 1 FROM descendants d JOIN dtmeta.tb_meta_data t3 ON t3.medata_set_id = d.medata_set_id WHERE t3.medata_val IS NOT NULL AND t3.medata_val != '' AND d.depth < 5
AND t3.prpty_id IN #{pid}
) SELECT m.type_model_id AS type_id , COALESCE(tm.model_logic_nm, tm.model_nm, m.type_model_id) AS type_name , COUNT(*) AS cnt FROM (SELECT DISTINCT medata_set_id FROM descendants WHERE medata_set_id != #{id}) d JOIN dtmeta.tb_meta_dataset ds ON ds.medata_set_id = d.medata_set_id AND ds.medata_set_sttus_mtcd != 'disuse' LEFT OUTER JOIN dtmeta.tb_meta_model m ON m.model_id = ds.model_id LEFT OUTER JOIN dtmeta.tb_meta_model tm ON tm.model_id = m.type_model_id GROUP BY m.type_model_id , COALESCE(tm.model_logic_nm, tm.model_nm, m.type_model_id) , tm.model_sort_odrg ORDER BY tm.model_sort_odrg NULLS LAST, type_name
